=== docs/adr/0003-rate-limits.md
     1	# 0003: Rate limits
     2	
     3	**Status:** Accepted
     4	
     5	All rate limits use `createLimiter` in `src/limiter.js`. Do not add another limiter.
     6	
     7	Authentication endpoints (login and password reset) allow 5 attempts per 15 minutes, keyed by client IP plus username. When the limit is hit, respond `429` with a `Retry-After` header in seconds. Successful attempts count toward the limit like failed ones, to keep the rule simple.
=== src/limiter.js
     1	// Shared fixed-window rate limiter. Every rate limit in this app uses it (ADR 0003).
     2	function createLimiter({ max, windowMs, key }) {
     3	  const hits = new Map();
     4	  return function check(req, now = Date.now()) {
     5	    const k = key(req); const entry = hits.get(k);
     6	    if (!entry || now - entry.start >= windowMs) { hits.set(k, { start: now, count: 1 }); return { ok: true }; }
     7	    entry.count += 1;
     8	    if (entry.count > max) return { ok: false, status: 429, retryAfterSec: Math.ceil((entry.start + windowMs - now) / 1000) };
     9	    return { ok: true };
    10	  };
    11	}
    12	module.exports = { createLimiter };
=== src/routes/login.js
     1	const users = new Map([['ana', 'correct-horse']]);
     2	function login(req) {
     3	  const ok = users.get(req.body.username) === req.body.password;
     4	  return ok ? { status: 200 } : { status: 401 };
     5	}
     6	module.exports = { login };
=== src/routes/password-reset.js
     1	const { createLimiter } = require('../limiter');
     2	const limit = createLimiter({ max: 5, windowMs: 15 * 60 * 1000, key: (req) => `${req.ip}:${req.body.username}` });
     3	function requestReset(req) {
     4	  const r = limit(req);
     5	  if (!r.ok) return { status: 429, headers: { 'Retry-After': String(r.retryAfterSec) } };
     6	  return { status: 202 };
     7	}
     8	module.exports = { requestReset };
=== test/password-reset.test.js
     1	const test = require('node:test'); const assert = require('node:assert');
     2	const { requestReset } = require('../src/routes/password-reset');
     3	test('sixth reset attempt in the window is limited', () => {
     4	  const req = { ip: '1.1.1.1', body: { username: 'ana' } };
     5	  for (let i = 0; i < 5; i++) assert.strictEqual(requestReset(req).status, 202);
     6	  const r = requestReset(req); assert.strictEqual(r.status, 429); assert.ok(r.headers['Retry-After']);
     7	});
SKILL.md
